/**
 * TypeScript definitions for rahad-all-downloader-v2
 * All-in-one social media video downloader
 */

export interface DownloaderMetadata {
  Author: string;
  message: string;
  Facebook: string;
}

/** Normalized response — same shape for every platform via `alldl(url)` */
export interface NormalizedData {
  title: string;
  videoUrl: string;
  source: string;
  download?: unknown;
}

export type QualityOption =
  | "best"
  | "high"
  | "medium"
  | "low"
  | "worst"
  | "audio"
  | `${number}p` // explicit height, e.g. "720p" — closest stream at or under it
  | `${number}`; // bare number, e.g. "720" — same as the "720p" form

export interface NormalizedResult {
  metadata: DownloaderMetadata;
  data: NormalizedData;
}

/** Full platform response — via `alldl.tiktok(url)` etc. */
export interface PlatformData {
  title?: string;
  author?: string;
  thumbnail?: string | null;
  download?: unknown;
  stats?: unknown;
  [key: string]: unknown;
}

export interface PlatformResult {
  metadata: DownloaderMetadata;
  success: boolean;
  source: string;
  data: PlatformData;
}

export interface AllDLOptions {
  /** How many times to retry transient failures (with backoff). Default: 2 */
  retries?: number;
  /**
   * Video quality: 'best' (default) | 'high' | 'medium' | 'low' | 'worst' |
   * 'audio' | explicit heights ('720p', '1080p', or bare '720').
   * Explicit heights pick the closest stream at or under the target (never
   * upscale); when nothing fits under it, the smallest stream above it.
   */
  quality?: QualityOption;
  /**
   * Cap the picked video height (e.g. `{ maxHeight: 720 }` → highest stream
   * with height <= 720). An explicit height inside `quality` wins over this.
   */
  maxHeight?: number;
  /**
   * Per-request proxy override. Single URL or an array
   * (array = round-robin rotation, one proxy per request).
   * Overrides the global `setProxy()` setting for this call only.
   * Inherited by DownloadOptions and BatchOptions.
   */
  proxy?: string | string[] | null;
}

export interface DownloadProgress {
  done: number;
  total: number | null;
  percent: number | null;
}

export interface DownloadOptions extends AllDLOptions {
  /** Progress callback: { done, total, percent } */
  onProgress?: (p: DownloadProgress) => void;
  /** Download audio only as .mp3 (TikTok music, Kwai audio, YouTube audio) */
  audioOnly?: boolean;
  /** Resume interrupted download from partial file (Range header) */
  resume?: boolean;
  /** Embed ID3 title+cover in MP3. Default: true */
  tag?: boolean;
}

/** YouTube playlist / TikTok profile / Instagram carousel item */
export interface PlaylistVideo {
  videoId: string;
  title: string;
  url: string;
  /**
   * Direct media URL (present for Instagram carousel items) — already
   * resolved, so download it directly instead of re-resolving.
   */
  mediaUrl?: string;
}

export interface PlaylistResult {
  title: string;
  count: number;
  videos: PlaylistVideo[];
}

export interface SubtitleResult {
  lang: string;
  srt: string;
  path?: string;
}

/** Per-source health entry — via `alldl.sourceHealth()` (2.9.0) */
export interface SourceHealthEntry {
  /** Consecutive failures since the last success */
  fails: number;
  /** True when the source is currently skipped (cooldown after repeated failures) */
  inCooldown: boolean;
  /** Remaining cooldown in ms; 0 when not in cooldown */
  cooldownEndsIn: number;
}

/** Source health map: `{ "tiktok:tikwm": { fails, inCooldown, cooldownEndsIn }, ... }` */
export interface SourceHealthMap {
  [sourceId: string]: SourceHealthEntry;
}

/** Source probe results: `{ platform: { sourceId: "up" | "down" } }` */
export interface SourceStatusMap {
  [platform: string]: { [sourceId: string]: "up" | "down" };
}

export interface DownloadResult {
  path: string;
  bytes: number;
  title: string;
  source: string;
  videoUrl: string;
}

export interface BatchOptions extends AllDLOptions {
  /** Max concurrent requests. Default: 3 */
  concurrency?: number;
  /** Called when each item completes */
  onItem?: (item: BatchItem, index: number) => void;
}

export type BatchItem =
  | ({ success: true; url: string } & NormalizedResult)
  | { success: false; url: string; error: string };

export interface XOptions {
  /** Quality preference, e.g. '720p' — selects the closest quality at or below it */
  quality?: string;
}

/** Metadata-only result — via `alldl.info(url)` (no download) */
export interface InfoAuthor {
  name: string | null;
  url: string | null;
}

export interface InfoResult {
  /** Detected site: 'tiktok' | 'youtube' | 'vimeo' | 'facebook' | 'instagram' | 'pinterest' | 'dailymotion' | 'reddit' | 'moj' | 'josh' | 'rumble' | 'twitch' | ... | 'unknown' */
  site: string;
  /** Alias of `site` — every info() result carries the same shape */
  platform: string;
  url: string;
  title: string | null;
  author: InfoAuthor;
  /** Flat uploader alias of `author.name` — null when unavailable */
  uploader: string | null;
  /** Seconds, or null when not available. TikTok thumbnails are signed CDN URLs — they expire */
  thumbnail: string | null;
  duration: number | null;
  description: string | null;
}

export interface InfoOptions {
  /** For Facebook/Instagram oEmbed: 'APP_ID|APP_SECRET' (user-supplied, never hardcode) */
  appToken?: string;
}

export interface AllDL {
  /** Auto-detect platform from URL → normalized `{ title, videoUrl, source }` */
  (url: string, opts?: AllDLOptions): Promise<NormalizedResult>;
  /**
   * Resolves and saves to disk as a file.
   * If `dest` is a folder, the filename is auto-generated from the title;
   * if it is a file path, that path is used as-is.
   */
  download(url: string, dest: string, opts?: DownloadOptions): Promise<DownloadResult>;
  /**
   * Batch many URLs at once — never throws.
   * Each item resolves to `{ success, ... }` or `{ success: false, error }`.
   */
  batch(urls: string[], opts?: BatchOptions): Promise<BatchItem[]>;
  /** TikTok — full data: no-watermark/watermark/music + stats */
  tiktok(url: string): Promise<PlatformResult>;
  /** Facebook — full data: HD/SD direct links */
  fb(url: string): Promise<PlatformResult>;
  /** Instagram — reels/posts/IGTV, no login needed */
  insta(url: string): Promise<PlatformResult>;
  /** Likee — direct video */
  likee(url: string): Promise<PlatformResult>;
  /** Threads — video & image extraction */
  threads(url: string): Promise<PlatformResult>;
  /** Pinterest — direct video */
  pinterest(url: string): Promise<PlatformResult>;
  /** YouTube — direct stream URL */
  youtube(url: string): Promise<PlatformResult>;
  /** CapCut — template video */
  capcut(url: string): Promise<PlatformResult>;
  /** Kwai — direct video */
  kwai(url: string): Promise<PlatformResult>;
  /** Dailymotion — HLS master stream */
  dailymotion(url: string): Promise<PlatformResult>;
  /** Vimeo — direct progressive MP4 */
  vimeo(url: string): Promise<PlatformResult>;
  /** X (Twitter) — multi-quality video & photo */
  x(url: string, opts?: XOptions): Promise<PlatformResult>;
  /** X (Twitter) — alias of `x` */
  twitter(url: string, opts?: XOptions): Promise<PlatformResult>;
  /** Snapchat — spotlight/stories video & photo */
  snapchat(url: string): Promise<PlatformResult>;
  /** Reddit — v.redd.it video + separate audio */
  reddit(url: string): Promise<PlatformResult>;
  /** Moj — direct video */
  moj(url: string): Promise<PlatformResult>;
  /** Josh — direct video */
  josh(url: string): Promise<PlatformResult>;
  /** Rumble — direct MP4 (or HLS when Rumble publishes no MP4) via oEmbed → embed page */
  rumble(url: string): Promise<PlatformResult>;
  /** Twitch clips — signed MP4 (360p via token source, up to 1080p via quality ladder) */
  twitch(url: string): Promise<PlatformResult>;
  /** TeraBox — share link file (2.11.0) */
  terabox(url: string): Promise<PlatformResult>;
  /** Google Drive — public file direct download link (2.12.0) */
  gdrive(url: string): Promise<PlatformResult>;
  /** MEGA — public file, AES-128-CTR decrypted on download (2.12.0) */
  mega(url: string): Promise<PlatformResult>;
  /** MediaFire — public file page scrape (2.12.0) */
  mediafire(url: string): Promise<PlatformResult>;
  /** Bilibili — video page + playurl API, no login (2.12.0) */
  bilibili(url: string): Promise<PlatformResult>;
  /** SoundCloud — track MP3 stream, client_id auto-discovered (2.12.0) */
  soundcloud(url: string): Promise<PlatformResult>;
  /** Spotify — 30-second MP3 preview (full tracks are DRM-protected) (2.12.0) */
  spotify(url: string): Promise<PlatformResult>;
  /** Douyin — video page play_addr scrape, watermark-free (2.12.0) */
  douyin(url: string): Promise<PlatformResult>;
  /** Xiaohongshu — note video/images via page data (2.12.0) */
  xiaohongshu(url: string): Promise<PlatformResult>;
  /** Deezer — track 30-second MP3 preview via public API (2.13.0) */
  deezer(url: string): Promise<PlatformResult>;
  /** Apple Music — track 30-second preview via iTunes lookup (2.13.0) */
  applemusic(url: string): Promise<PlatformResult>;
  /** Bandcamp — track MP3 stream via page data (2.13.0) */
  bandcamp(url: string): Promise<PlatformResult>;
  /** Pixeldrain — file direct download via public API (2.13.0) */
  pixeldrain(url: string): Promise<PlatformResult>;
  /** Gofile — file direct download via public API (2.13.0) */
  gofile(url: string): Promise<PlatformResult>;
  /** Odysee — video MP4 via LBRY proxy API (2.13.0) */
  odysee(url: string): Promise<PlatformResult>;
  /** PeerTube — video via instance ActivityPub API (2.13.0) */
  peertube(url: string): Promise<PlatformResult>;
  /** Kick — clip HLS via public clips API v2 (2.13.0) */
  kick(url: string): Promise<PlatformResult>;
  /** VK Video — video MP4 via embed page (2.13.0) */
  vk(url: string): Promise<PlatformResult>;
  /** Weibo — video MP4 via mobile API (2.13.0) */
  weibo(url: string): Promise<PlatformResult>;
  /** Mixcloud — show audio stream via GraphQL API (2.13.0) */
  mixcloud(url: string): Promise<PlatformResult>;
  /** Audiomack — track audio stream via OAuth-signed API (2.13.0) */
  audiomack(url: string): Promise<PlatformResult>;
  dropbox(url: string): Promise<PlatformResult>;
  archiveorg(url: string): Promise<PlatformResult>;
  applepodcasts(url: string): Promise<PlatformResult>;
  audius(url: string): Promise<PlatformResult>;
  streamable(url: string): Promise<PlatformResult>;
  tumblr(url: string): Promise<PlatformResult>;
  bluesky(url: string): Promise<PlatformResult>;
  hearthisat(url: string): Promise<PlatformResult>;
  freemusicarchive(url: string): Promise<PlatformResult>;
  boxcom(url: string): Promise<PlatformResult>;
  box(url: string): Promise<PlatformResult>;
  onedrive(url: string): Promise<PlatformResult>;
  loom(url: string): Promise<PlatformResult>;
  rutube(url: string): Promise<PlatformResult>;
  okru(url: string): Promise<PlatformResult>;
  bitchute(url: string): Promise<PlatformResult>;
  /**
   * Metadata only — no download. Returns a consistent shape for every site:
   * `{ site, platform, url, title, author:{name,url}, uploader, thumbnail, duration, description }`.
   * Unavailable fields are `null`, never fabricated data.
   * For Facebook/Instagram, pass `{ appToken: 'APP_ID|APP_SECRET' }`.
   */
  info(url: string, opts?: InfoOptions): Promise<InfoResult>;
  /**
   * Set the HTTP timeout (ms) for API resolve calls. Default 20000.
   * Increase it for slow networks: `alldl.setTimeout(45000)`.
   */
  setTimeout(ms: number): number;
  /** Current HTTP timeout (ms) for API resolve calls. */
  getTimeout(): number;
  /**
   * Proxy for all requests (geo-block / IP ban bypass).
   * `alldl.setProxy('http://user:pass@host:port')` — one proxy for all requests.
   * `alldl.setProxy(['http://p1:8080', 'http://p2:8080'])` — round-robin rotation,
   * one proxy per request. `alldl.setProxy(null)` — proxy off.
   */
  setProxy(proxyUrl: string | string[] | null): unknown;
  /** Current proxy setting: `string | string[] | null` (null = disabled) */
  getProxy(): string | string[] | null;
  /**
   * Start self-hosted downloader API + web UI.
   * `const server = await alldl.serve({ port: 3000, apiKey: 'SECRET' })`
   */
  serve(opts?: { port?: number; apiKey?: string }): Promise<unknown>;
  /**
   * YouTube playlist OR TikTok user profile OR Instagram carousel post →
   * `{ title, count, videos: [{ videoId, title, url, mediaUrl? }] }`.
   * Instagram carousel entries carry `mediaUrl` (a direct CDN URL) — download
   * it directly instead of re-resolving.
   * Pair with `batch()` + `download()` to grab the whole playlist.
   */
  playlist(url: string, opts?: { limit?: number }): Promise<PlaylistResult>;
  /**
   * YouTube subtitles → `{ lang, srt, path? }`.
   * Pass `{ dest }` to save as .srt file, `{ lang: 'bn' }` for Bangla.
   */
  subtitles(url: string, opts?: { lang?: string; dest?: string }): Promise<SubtitleResult>;
  /**
   * Live per-source health for every registered source (2.9.0):
   * `{ "tiktok:tikwm": { fails, inCooldown, cooldownEndsIn }, ... }`.
   * Sources that fail 3 times in a row are skipped for 10 minutes;
   * any success resets the counter. Never throws.
   */
  sourceHealth(): SourceHealthMap;
  /**
   * Probe every registered source (2.9.0) — cheap status checks, no video
   * downloads. Returns `{ platform: { sourceId: "up" | "down" } }`.
   * Never throws: a failed probe is reported as "down".
   */
  checkSources(): Promise<SourceStatusMap>;
}

export declare const alldl: AllDL;
